#include <condition_variable>
#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<long long> values;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    std::mutex guard;
    std::condition_variable signal;
    bool ready = false;
    long long total = 0;
    std::thread worker([&]() {
        long long local = 0;
        for (long long value : values) local += value;
        {
            std::lock_guard<std::mutex> locked(guard);
            total = local;
            ready = true;
        }
        signal.notify_one();
    });
    {
        std::unique_lock<std::mutex> locked(guard);
        signal.wait(locked, [&] { return ready; });
    }
    worker.join();
    std::cout << total << std::endl;
    return 0;
}
